    n = 21
    for a in range(1, n // 2 + 1):
        for b in range(a + 1, n // 2 + 1):
            edges = []
            for i in range(n):
                edges.append((i, (i + a) % n))
                edges.append((i, (i + b) % n))

            # Remove duplicates and self-loops
            unique_edges = set()
            for u, v in edges:
                if u == v: continue
                if u > v: u, v = v, u
                unique_edges.add((u, v))

            if len(unique_edges) != 2 * n: continue

            if get_girth(n, unique_edges) >= 5:
